  function exams() { let arr = db.attempts.filter(a => a.submittedAt); return pageHead('YOUR PRACTICE HISTORY', 'My exams', 'Review your attempts and see how your practice is progressing.', `<button class="btn primary" data-page="create-exam">＋ Create exam</button>`) + (arr.length ? `<div class="panel table-card"><div class="table-head" style="grid-template-columns:2fr 1fr 100px 100px"><div>EXAM</div><div>COMPLETED</div><div>SCORE</div><div></div></div>${arr.map(a => `<div class="table-item" style="grid-template-columns:2fr 1fr 100px 100px"><div class="row-main"><b>${esc(a.name)}</b><small>${a.questions.length} question${a.questions.length === 1 ? '' : 's'} · ${a.topicName?esc(a.topicName):a.scope==='subject'?'Subject-wide':'Custom exam'}</small></div><div>${fmtDate(a.submittedAt)}</div><div><span class="badge ${a.score / a.questions.length < .6 ? 'warn' : ''}">${Math.round(a.score / a.questions.length * 100)}%</span></div><div class="row-actions"><button class="btn small" data-action="result-view" data-id="${a.id}">Review</button></div></div>`).join('')}</div>` : `<div class="panel empty">No completed exams yet. Your saved attempts will live here.</div>`); }
  function cardsPage() { return pageHead('SMALL CARDS, STEADY PROGRESS', 'Flashcards', 'Review difficult cards sooner with simple spaced repetition.', `<button class="btn" data-action="smart-revision">Smart revision</button><button class="btn" data-action="card-study">Study due cards</button><button class="btn primary" data-action="card-add">＋ Add card</button>`) + `<div class="toolbar"><input class="search" id="card-search" placeholder="Search cards…"><span class="page-sub">${db.cards.filter(c => !c.due || c.due <= today()).length} due now · ${db.cards.length} total</span></div>${db.cards.length ? `<div class="panel table-card">${db.cards.map(c => `<div class="table-item" style="grid-template-columns:2fr 1fr 100px 100px"><div class="question-text">${esc(c.front)}</div><div>${esc(subjectName(c.subjectId))}</div><div><span class="badge">${esc(c.interval || 0)} day interval</span></div><div class="row-actions"><button class="icon-btn" data-action="card-edit" data-id="${c.id}">✎</button><button class="icon-btn" data-action="card-delete" data-id="${c.id}">×</button></div></div>`).join('')}</div>` : `<div class="panel empty">No cards yet. Add a card to start building your review deck.</div>`}`; }
  function mistakeCount() { return Object.entries(db.reviews).filter(([id, r]) => db.questions.some(q => q.id === id) && r.wrong > 0 && !r.mastered && !r.dismissed).length; }
  function mistakes() { let qs = db.questions.filter(q => { let r = db.reviews[q.id] || {}; return r.wrong > 0 && !r.mastered && !r.dismissed; }).sort((a, b) => (db.reviews[b.id]?.wrong || 0) - (db.reviews[a.id]?.wrong || 0)); return pageHead('LEARN FROM THE MISSES', 'My mistakes', 'Questions you’ve missed, with the original answer history kept intact.', qs.length ? `<button class="btn primary" data-action="mistake-practice">Practice ${qs.length} questions</button>` : '') + (qs.length ? `<div class="panel table-card">${qs.map(q => { let r = db.reviews[q.id]; return `<div class="table-item" style="grid-template-columns:2fr 1fr 100px 140px"><div class="question-text">${mathHtml(q.text)}</div><div>${esc(subjectName(q.subjectId))}</div><div><span class="badge rose">${r.wrong} ${r.wrong === 1 ? 'miss' : 'misses'}</span></div><div class="row-actions"><button class="icon-btn" data-action="mistake-master" data-id="${q.id}">✓ Master</button><button class="icon-btn" data-action="mistake-dismiss" data-id="${q.id}">×</button></div></div>` }).join('')}</div>` : `<div class="panel empty"><div class="empty-icon">✦</div>No open mistakes. Keep going at your own pace.</div>`); }
  function statistics() { let done = db.attempts.filter(a => a.submittedAt), bySubject = db.subjects.map(s => { let as = done.filter(a => a.subjectId === s.id), pct = as.length ? Math.round(as.reduce((x, a) => x + a.score / a.questions.length * 100, 0) / as.length) : 0; return [s.name, pct, as.length] }); let total = Object.values(db.reviews).reduce((a, r) => a + r.wrong + r.correct, 0), wrong = Object.values(db.reviews).reduce((a, r) => a + r.wrong, 0); return pageHead('A CLEARER PICTURE', 'Statistics', 'Use your practice history to decide what to study next.') + `<div class="grid stats-grid">${stat('Exam average', metrics().avg + '%', `${done.length} completed exams`, '◌')}${stat('Questions answered', total, 'Across all saved attempts', '☷')}${stat('Incorrect answers', wrong, `${total ? Math.round(wrong / total * 100) : 0}% of tracked responses`, '↗')}${stat('Study streak', `${db.streak || 0} days`, 'Keep your rhythm gentle', '✦')}</div><div class="grid dashboard-grid"><div class="panel"><div class="panel-head"><h2 class="panel-title">Performance by subject</h2></div>${bySubject.length ? bySubject.map(([name, pct, n]) => `<div class="bar-row"><span>${esc(name)}</span><div class="progress"><i style="width:${pct}%"></i></div><b>${n ? pct + '%' : '—'}</b></div>`).join('') : `<div class="empty">Add subjects and complete an exam to see performance here.</div>`}</div><div class="panel"><div class="panel-head"><h2 class="panel-title">Topics to revisit</h2></div>${db.questions.map(q => ({ q, r: db.reviews[q.id] || { wrong: 0 } })).filter(x => x.r.wrong).sort((a, b) => b.r.wrong - a.r.wrong).slice(0, 5).map(({ q, r }) => `<div class="activity-row"><span class="dot" style="background:#bf766d"></span><div class="row-main"><b>${mathHtml(q.text)}</b><small>${esc(subjectName(q.subjectId))}</small></div><span class="row-meta">${r.wrong}×</span></div>`).join('') || `<div class="empty">Question patterns will appear after your first exam.</div>`}</div></div>`; }
  function settings() { return pageHead('YOUR STUDYROOM', 'Settings', 'Keep your data safe and make this space feel like yours.') + `<div class="grid dashboard-grid"><div class="panel"><h2 class="panel-title">Appearance</h2><p class="page-sub" style="margin:8px 0 18px">Switch between the warm light theme and a softer dark theme.</p><label>Dark appearance <input class="toggle" type="checkbox" id="dark-setting" ${db.settings.dark ? 'checked' : ''}></label></div><div class="panel"><h2 class="panel-title">Your data</h2><p class="page-sub" style="margin:8px 0 18px">Your materials and study history are stored in this browser.</p><div class="actions"><button class="btn" data-action="export">Export backup</button><button class="btn" data-action="import">Restore backup</button><button class="btn danger" data-action="clear-data">Clear all data</button></div></div></div>`; }
  function render() { shell(); let out = page === 'dashboard' ? dashboard() : page === 'subjects' ? subjects() : page === 'subject-detail' ? subjectDetail() : page === 'topic-detail' ? topicDetail() : page === 'questions' ? questions() : page === 'smart-import' ? smartImport() : page === 'import-preview' ? previewImport() : page === 'import-working' ? `<div class="panel import-progress"><div class="import-icon">✦</div><h2 class="panel-title">Organizing your questions…</h2><p class="page-sub">Checking lines, choices, answer keys, and possible formatting issues.</p><div class="progress"><i></i></div></div>` : page === 'create-exam' ? createExam() : page === 'exams' ? exams() : page === 'flashcards' ? cardsPage() : page === 'mistakes' ? mistakes() : page === 'statistics' ? statistics() : page === 'settings' ? settings() : page === 'run-exam' ? runExam() : page === 'result' ? resultLookup() : page === 'study-cards' ? studyCards() : settings(); $('#view').innerHTML = out; $('#modal-root').innerHTML = modal || ''; renderMath($('#view')); renderMath($('#modal-root')); if (page === 'create-exam') refreshExamBuilder(); }
  function notify(s) { let t = $('#toast'); t.textContent = s; t.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove('show'), 2300); }
  function analyzeImport() { let raw = $('#import-raw')?.value || importDraft.raw; if (!raw.trim()) { notify('Paste some question text first.'); return; } if(!$('#import-subject')?.value||!$('#import-topic')?.value){notify('Choose a subject and topic before analyzing these questions.');return;} importDraft.raw = raw; importDraft.subjectId = $('#import-subject')?.value || ''; importDraft.topic = $('#import-topic')?.value.trim() || ''; importDraft.hash = textHash(raw.trim().replace(/\s+/g, ' ')); importDraft.duplicate = (db.importHashes || []).includes(importDraft.hash); db.importDraft = JSON.parse(JSON.stringify(importDraft)); save(); let mode = $('#import-type')?.value || 'auto'; importDraft.type = mode; page = 'import-working'; render(); setTimeout(() => { let found = parseBulkQuestions(raw); if (mode !== 'auto') found.forEach(q => { let previous = q.type; q.type = mode; if (mode === 'mcq') { q.options = q.options.length ? q.options : ['', '']; if (previous !== 'mcq') q.correct = null; if (q.options.length < 2 && !q.warnings.some(w => w.includes('fewer than'))) q.warnings.push('This multiple-choice question has fewer than two choices.'); if (q.options.some(x => !x.trim()) && !q.warnings.some(w => w.includes('choices are empty'))) q.warnings.push('One or more answer choices are empty.'); } else { q.options = []; if (previous !== mode) q.correct = null; } if (q.correct === null && !q.warnings.some(w => w.includes('No correct answer'))) q.warnings.push('No correct answer was detected. Confirm or add it before using this question in an exam.'); }); const seenText = new Set(); found.forEach(q => { let normalized = q.text.trim().toLowerCase(); if (normalized && seenText.has(normalized)) q.warnings.push('This question text duplicates another question in this import.'); if (normalized) seenText.add(normalized); if (normalized && db.questions.some(old => old.text.trim().toLowerCase() === normalized)) q.warnings.push('A question with matching text is already in your bank.'); }); importDraft.questions = found; db.importDraft = JSON.parse(JSON.stringify(importDraft)); save(); page = 'import-preview'; render(); }, 80); }
  function commitImported(all = false) { let selected = all ? importDraft.questions : importDraft.questions.filter(q => q.selected); if (!selected.length) { notify('Select at least one question to import.'); return; } let repeats = selected.filter(q => q.warnings.some(w => w.includes('matching text is already in your bank') || w.includes('duplicates another question'))).length; if ((importDraft.duplicate || repeats) && !confirm(`${importDraft.duplicate ? 'This pasted text was imported before. ' : ''}${repeats ? `${repeats} selected question${repeats === 1 ? '' : 's'} match existing question text. ` : ''}Import anyway?`)) return; const imported = selected.map(q => ({ id: uid(), text: q.text.trim(), type: q.type, options: q.type === 'mcq' ? q.options.map(x => x.trim()) : [], correct: q.correct, explanation: q.explanation.trim(), subjectId: importDraft.subjectId, topic: importDraft.topic, sourceNumber: q.sourceNumber || q.number, importWarnings: q.warnings })); db.questions.push(...imported); delete db.importDraft; if (selected.length === importDraft.questions.length) { db.importHashes = db.importHashes || []; if (!db.importHashes.includes(importDraft.hash)) db.importHashes.push(importDraft.hash); } save(); searchText = ''; filters = { type: 'all', subject: 'all' }; page = 'questions'; notify(`${imported.length} question${imported.length === 1 ? '' : 's'} added to your question bank.`); render(); }
  function showModal(title, body, submitLabel = 'Save') { modal = `<div class="modal-backdrop" data-action="modal-close"><form class="modal" id="modal-form"><h2>${title}</h2>${body}<div class="modal-actions"><button type="button" class="btn" data-action="modal-cancel">Cancel</button><button class="btn primary" type="submit">${submitLabel}</button></div></form></div>`; render(); }
  function topicOptions(subjectId,selected='') { let s=db.subjects.find(x=>x.id===subjectId);return `<option value="">Unassigned</option>${topicList(s).map(t=>`<option value="${esc(t)}" ${selected===t?'selected':''}>${esc(t)}</option>`).join('')}`; }
  function updateMaterialTopics(form,subjectId) { let select=form?.querySelector('[name=topic]'),previous=select?.value||'';if(!select)return;select.innerHTML=topicOptions(subjectId,previous);if(previous&&!topicList(db.subjects.find(s=>s.id===subjectId)).includes(previous))select.value=''; }
  function updateImportTopics(subjectId) { let select=$('#import-topic'),previous=select?.value||importDraft.topic;if(!select)return;select.innerHTML=`<option value="">Unassigned</option>${topicList(db.subjects.find(s=>s.id===subjectId)).map(t=>`<option value="${esc(t)}" ${t===previous?'selected':''}>${esc(t)}</option>`).join('')}`;if(!topicList(db.subjects.find(s=>s.id===subjectId)).includes(previous))select.value='';importDraft.topic=select.value;persistImportDraft(); }
  function subjectOptions(selected = '') { return `<option value="">Unsorted</option>${db.subjects.map(s => `<option value="${s.id}" ${selected === s.id ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}`; }
  function questionForm(q) { q = q || { type: 'mcq', options: ['', '', '', ''], correct: 0 }; let options = `<div class="form-field full" id="options-wrap" style="${q.type !== 'mcq' ? 'display:none' : ''}"><span>Answer choices <small>LaTeX is rendered in each preview and in the exam.</small></span>${(q.options?.length ? q.options : ['', '', '', '']).map((o, i) => `<div class="option-row"><input type="radio" name="correct" value="${i}" ${q.correct === i ? 'checked' : ''} aria-label="Mark option ${i + 1} as correct"><input class="field" name="option" value="${esc(o)}" placeholder="Option ${i + 1}" ${q.type === 'mcq' ? 'required' : ''}><div class="math-preview" ${hasMath(o)?"":"hidden"}><b>Choice ${String.fromCharCode(65+i)} preview</b><div data-math-preview="option-${i}">${mathHtml(o)}</div></div></div>`).join('')}</div>`; return `<div class="form-grid"><label class="form-field full">Question<textarea required class="field" name="text">${esc(q.text || '')}</textarea><div class="math-preview" ${hasMath(q.text || "")?"":"hidden"}><b>Math preview</b><div data-math-preview="question">${mathHtml(q.text || '')}</div></div></label><label class="form-field">Type<select class="field" name="type"><option value="mcq" ${q.type === 'mcq' ? 'selected' : ''}>Multiple choice</option><option value="tf" ${q.type === 'tf' ? 'selected' : ''}>True / False</option><option value="short" ${q.type === 'short' ? 'selected' : ''}>Short answer</option></select></label><label class="form-field">Subject<select class="field" required name="subjectId">${subjectOptions(q.subjectId)}</select></label><label class="form-field full">Topic<select class="field" required name="topic">${topicOptions(q.subjectId,q.topic)}</select></label>${options}<label class="form-field full" id="tf-wrap" style="${q.type === 'tf' ? '' : 'display:none'}">Correct answer<select name="tfcorrect" class="field"><option value="" ${q.correct === null ? 'selected' : ''}>Not provided</option><option value="true" ${q.correct === true ? 'selected' : ''}>True</option><option value="false" ${q.correct === false ? 'selected' : ''}>False</option></select></label><label class="form-field full" id="short-wrap" style="${q.type === 'short' ? '' : 'display:none'}">Expected answer<input name="shortcorrect" class="field" value="${esc(q.correct ?? '')}" placeholder="Leave blank if not known"><div class="math-preview" ${hasMath(q.correct ?? "")?"":"hidden"}><b>Math preview</b><div data-math-preview="correct">${mathHtml(q.correct ?? '')}</div></div></label><label class="form-field full">Explanation<textarea class="field" name="explanation">${esc(q.explanation || '')}</textarea><div class="math-preview" ${hasMath(q.explanation || "")?"":"hidden"}><b>Math preview</b><div data-math-preview="explanation">${mathHtml(q.explanation || '')}</div></div></label></div>`; }
  function cardForm(c = {}) { return `<div class="form-grid"><label class="form-field full">Front<textarea required class="field" name="front">${esc(c.front || '')}</textarea></label><label class="form-field full">Back<textarea required class="field" name="back">${esc(c.back || '')}</textarea></label><label class="form-field">Subject<select class="field" required name="subjectId">${subjectOptions(c.subjectId)}</select></label><label class="form-field">Topic<select class="field" required name="topic">${topicOptions(c.subjectId,c.topic)}</select></label></div>`; }
  function subjectForm(s = {}) { return `<div class="form-grid"><label class="form-field full">Subject name<input required class="field" name="name" value="${esc(s.name || '')}"></label><label class="form-field full">Description<textarea class="field" name="description">${esc(s.description || '')}</textarea></label><label class="form-field">Accent color<select class="field" name="color"><option value="#8565b5" ${s.color === '#8565b5' ? 'selected' : ''}>Violet</option><option value="#c08078" ${s.color === '#c08078' ? 'selected' : ''}>Rose</option><option value="#6486a5" ${s.color === '#6486a5' ? 'selected' : ''}>Blue</option><option value="#bd9558" ${s.color === '#bd9558' ? 'selected' : ''}>Amber</option></select></label><label class="form-field full">Topics <small>Separate initial topics with commas. Manage individual topics from the subject page.</small><input class="field" name="topics" value="${esc((s.topics || []).join(', '))}"></label></div>`; }
  function topicForm(name = '', description = '') { return `<div class="form-grid"><label class="form-field full">Topic name<input required class="field" name="topicName" value="${esc(name)}"></label><label class="form-field full">Description<textarea class="field" name="topicDescription">${esc(description)}</textarea></label></div>`; }
  function startAttempt(name, subjectId, questions, opts = {}) { resultTopicFilter='';let a = { id: uid(), examId: opts.examId || null, name, subjectId, topicName: opts.topicName || null, scope: opts.scope || 'general', topicCounts: opts.topicCounts || null, questions: questions.map(q => JSON.parse(JSON.stringify(q))), answers: Array(questions.length).fill(null), marked: [], startedAt: new Date().toISOString(), minutes: opts.minutes || null, pass: opts.pass || null, instructions: opts.instructions || '', submittedAt: null, score: 0 }; db.attempts.unshift(a); save(); examRun = a.id; page = 'run-exam'; render(); }
  function currentAttempt() { return db.attempts.find(a => a.id === examRun); }
  function answerLabel(q, a) { if (a === null || a === undefined || a === '') return 'No answer'; return q.type === 'mcq' ? q.options[a] : q.type === 'tf' ? (a ? 'True' : 'False') : String(a); }
  function isCorrect(q, answer) { if (answer === null || answer === undefined || answer === '') return false; if (q.type === 'short') return String(answer).trim().toLocaleLowerCase() === String(q.correct ?? '').trim().toLocaleLowerCase(); return answer === q.correct; }
  function attemptScore(a) { return a.questions.reduce((n, q, i) => n + (isCorrect(q, a.answers[i]) ? 1 : 0), 0); }
  function runExam() { let a = currentAttempt(); if (!a) { page = 'exams'; return exams(); } let i = a.current || 0, q = a.questions[i], val = a.answers[i]; return `<div class="page-head"><div><div class="eyebrow">${esc(a.name)}</div><h1 class="page-title">Question ${i + 1} <span style="color:var(--muted);font:16px var(--sans)">of ${a.questions.length}</span></h1><p class="page-sub">${esc(subjectName(a.subjectId))}${a.instructions ? ' · ' + esc(a.instructions) : ''}</p></div><button class="btn" data-action="exam-submit">Submit exam</button></div><div class="progress" style="margin:-12px 0 17px"><i style="width:${(i + 1) / a.questions.length * 100}%"></i></div><div class="exam-layout"><div class="panel exam-card"><span class="badge">${q.type === 'mcq' ? 'MULTIPLE CHOICE' : q.type === 'tf' ? 'TRUE / FALSE' : 'SHORT ANSWER'}${q.topic ? ' · ' + esc(q.topic) : ''}</span><div class="exam-question">${mathHtml(q.text)}</div>${q.type === 'mcq' ? q.options.map((o, j) => `<label class="answer-option ${val === j ? 'selected' : ''}"><input type="radio" name="answer" value="${j}" ${val === j ? 'checked' : ''}>${mathHtml(o)}</label>`).join('') : q.type === 'tf' ? [true, false].map(x => `<label class="answer-option ${val === x ? 'selected' : ''}"><input type="radio" name="answer" value="${x}" ${val === x ? 'checked' : ''}>${x ? 'True' : 'False'}</label>`).join('') : `<label class="form-field">Your answer<input class="field" name="answer-text" value="${esc(val || '')}" autocomplete="off"></label>`}<div class="exam-nav"><button class="btn" data-action="exam-prev" ${i === 0 ? 'disabled' : ''}>← Previous</button><button class="btn" data-action="exam-mark">${a.marked.includes(i) ? '★ Marked' : '☆ Mark for review'}</button><button class="btn primary" data-action="exam-next">${i === a.questions.length - 1 ? 'Finish' : 'Next →'}</button></div></div><div class="panel exam-side"><div class="panel-head"><h2 class="panel-title" style="font-size:17px">Question map</h2></div><div class="q-grid">${a.questions.map((_, j) => `<button class="q-num ${j === i ? 'current' : ''} ${a.answers[j] !== null ? 'done' : ''}" data-action="exam-jump" data-index="${j}">${j + 1}${a.marked.includes(j) ? '★' : ''}</button>`).join('')}</div><p class="page-sub" style="margin-top:15px">${a.answers.filter(x => x !== null).length} answered · ${a.questions.length - a.answers.filter(x => x !== null).length} remaining</p>${a.minutes ? `<span class="badge warn" id="timer" data-start="${new Date(a.startedAt).getTime()}" data-minutes="${a.minutes}">⏱ ${a.minutes}:00</span>` : ''}</div></div>`; }
  function resultPage(a) {
    let indices=a.questions.map((q,i)=>i);
    if(resultTopicFilter){const subject=db.subjects.find(s=>s.id===a.subjectId);indices=indices.filter(i=>topicMatches(a.questions[i],subject,resultTopicFilter));}
    if(!indices.length)indices=a.questions.map((q,i)=>i);
    let correct=indices.filter(i=>isCorrect(a.questions[i],a.answers[i])).length,unanswered=indices.filter(i=>a.answers[i]===null).length,wrong=indices.length-correct-unanswered,pct=indices.length?Math.round(correct/indices.length*100):0;
    return `<div style="text-align:center;margin:10px 0 26px"><div class="eyebrow">${resultTopicFilter?'TOPIC RESULT':'ATTEMPT COMPLETE'}</div><h1 class="page-title" style="margin-bottom:20px">${esc(a.name)}</h1>${resultTopicFilter?`<p class="page-sub">${esc(resultTopicFilter)} · ${indices.length} questions in this topic</p>`:''}<div class="result-score" style="--score:${pct*3.6}deg"><b>${pct}%</b></div><p class="page-sub" style="margin-top:13px">${correct} correct · ${wrong} incorrect · ${unanswered} unanswered${a.pass&&!resultTopicFilter?` · ${pct>=a.pass?'Passed':'Passing score: '+a.pass+'%'}`:''}</p><div class="actions" style="justify-content:center;margin-top:18px"><button class="btn" data-action="retake-all" data-id="${a.id}">Retake entire exam</button>${wrong?`<button class="btn" data-action="retake-wrong" data-id="${a.id}">Retry incorrect only</button>`:''}<button class="btn primary" data-page="exams">Exam history</button></div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Answer review</h2><button class="panel-link" data-action="review-only" data-id="${a.id}">STUDY ANSWERS</button></div>${indices.map(i=>{let q=a.questions[i],unanswered=a.answers[i]===null,ok=isCorrect(q,a.answers[i]);return `<div class="review-item"><span class="badge ${ok?'':unanswered?'warn':'rose'}">${ok?'Correct':unanswered?'Unanswered':'Review'} · ${i+1}</span><h4>${mathHtml(q.text)}</h4><p><b>Your answer:</b> ${mathHtml(answerLabel(q,a.answers[i]))}</p><p><b>Correct answer:</b> ${mathHtml(answerLabel(q,q.correct))}</p>${q.explanation?`<p class="page-sub answer-explanation">${mathHtml(q.explanation)}</p>`:''}</div>`}).join('')}</div>`;
  }
  function resultLookup() { let a = db.attempts.find(a => a.id === examRun); return a ? resultPage(a) : exams(); }
